insert into feh.skills (wiki_name,name,group_name,tag_id,scategory,use_range,refine_path,description,required,next,exclusive,sp,can_use_move,can_use_weapon,might,stat_modifiers,cooldown,weapon_effectiveness,properties) values
  ('Aethers Route','Aether''s Route','Aether''s Route','SID_正真蒼炎の天空','special',null,null,'When Special triggers, boosts damage by the greater of unit''s or foe''s Def and restores 50% of unit''s maximum HP.<br><br>At start of player phase or enemy phase, grants【Radiant Hero】and "reduces the percentage of foe''s non-Special ''reduce damage by X%'' skills by 50% during combat (excluding area-of-effect Specials)" to unit and allies within 2 spaces of unit for 1 turn.<br><br>Foe can make a follow-up attack before unit''s next attack during combat.<br><br>Neutralizes effects that inflict "Special cooldown charge -X" on unit, reduces the effect of【Deep Wounds】by 50%, neutralizes effects that prevent unit''s counterattacks, and reduces damage from foe''s attacks by 40%, but if unit receives consecutive attacks, reduces damage from foe''s second attack onward by 70% during combat (excluding area-of-effect Specials).<br><br>【Radiant Hero】<br>Unit can counterattack regardless of foe''s range.<br><br>Grants Atk/Spd/Def/Res+5 to unit and reduces damage from foe''s first attack by 10 during combat ("first attack" normally means only the first strike; for effects that grant "unit attacks twice," it means the first and second strikes), and also, when Special triggers, deals damage = unit''s max Special cooldown count value × 4 (excluding area-of-effect Specials).<br><br>【Deep Wounds】<br>Unit''s HP cannot be healed through its next action.','Sol;Luna',null,true,500,'Infantry,  Armored,  Cavalry,  Flying',null,null,null,5,null,'offensive_special,random_owner'),
  ('AS Tenet Hone','A/S Tenet Hone','A/S Tenet Hone','SID_攻速信念・弱化無効','passivec',null,null,'At start of player phase or enemy phase, grants 【Bulwark】to unit for 1 turn, and grants Atk/Spd+6 and "neutralizes penalties on unit during combat" to unit and allies within 2 spaces of unit for 1 turn.<br><br>Grants bonus to unit''s Atk/Spd = number of allies within 3 rows or 3 columns centered on unit × 2 (max 6), unit deals +5 damage (excluding area-of-effect Specials), and reduces damage from foe''s first attack by 5 during combat ("first attack" normally means only the first strike; for effects that grant "unit attacks twice," it means the first and second strikes).<br><br>【Bulwark】<br>Foes with Range = 1 cannot move through spaces adjacent to unit (does not affect foes with Pass skills). Foes with Range = 2 cannot move through spaces within 2 spaces of unit (does not affect foes with Pass skills).','AtkSpd Oath 3',null,false,300,'Infantry','Red Sword,  Blue Lance,  Green Axe,  Red Breath,  Blue Breath,  Green Breath,  Colorless Breath,  Red Beast,  Blue Beast,  Green Beast,  Colorless Beast',null,'0,0,0,0,0',null,null,'random_owner'),
  ('Chiseled Antler','Chiseled Antler','Chiseled Antler','SID_運動する体の角','weapon',1,null,'Enables【Canto (Dist. +1; Max ４)】. Accelerates Special trigger (cooldown count-1).<br><br>At start of player phase or enemy phase, grants Atk/Def+6,【Drain Cancel】, and【Null Panic】to unit and allies within 2 spaces of unit for 1 turn.<br><br>If unit or allies within 2 spaces of unit have bonuses to Atk/Spd/Def/Res after start-of-turn skills trigger, or, if defending in Aether Raids, after start-of-turn skills trigger at the start of turn 1 of enemy phase, grants an additional +3 to each corresponding stat for unit and those allies for 1 turn (calculates each stat bonus independently; max 10).<br><br>Grants Atk/Def/Res+16 to unit, unit deals +X damage (excluding area-of-effect Specials), reduces damage from foe''s attacks by 50% of X (excluding area-of-effect Specials), reduces damage from foe''s Specials by an additional 50% of X (excluding area-of-effect Specials; X = highest total bonuses among unit and allies within 3 rows or 3 columns centered on unit), and reduces the percentage of foe''s non-Special "reduce damage by X%" skills by 50% during combat (excluding area-of-effect Specials).<br><br>At start of turn, if unit is adjacent to only beast or dragon allies or if unit is not adjacent to any ally, unit transforms (otherwise, unit reverts). If unit transforms, grants Atk+2 to unit, inflicts Atk/Def-Y on foe during combat (Y = number of spaces from start position to end position of whoever initiated combat + 3; max 6), and also, if Y ≥ 5, reduces damage from foe''s first attack by 30% during combat.<br><br>【Canto (Dist. +1; Max ４)】<br>After an attack, Assist skill, or structure destruction, unit can move spaces = number of spaces from start position to end position of unit before the above, +1. (Max ４.)<br><br>【Drain Cancel】<br>Grants Atk/Spd/Def/Res+4 to unit during combat.<br><br>When a foe triggers both "grants the【Bonus】 effects active on foe" and "neutralizes any 【Bonus】active on foe" effects from skills such as Essence Drain on unit with this status active, prevents those effects on unit and other targets and neutralizes any【Bonus】effects active on that foe (does not neutralize【Bonus】 effects applied at the same time).<br><br>【Null Panic】<br>If unit is inflicted with Panic (bonuses converted into penalties), neutralizes the "converts bonuses on target into penalties" effect for 1 turn.<br><br>【Bonus】<br>All effects that last "for 1 turn" or "that turn only." Includes bonuses granted by a skill like Rally or Hone and positive status effects (extra movement or effects like Dominance).','Adult Cavalry',null,true,400,'Cavalry','Red Beast,  Blue Beast,  Green Beast,  Colorless Beast',14,'0,14,0,0,0',-1,null,null),
  ('Counter Dull','Counter Dull','Counter Dull','SID_合気・強化無効','passiveb',null,null,'If a skill compares unit''s Spd to a foe''s or ally''s Spd, treats unit''s Spd as if granted +7.<br><br>Reduces damage from area-of-effect Specials by 80% (excluding Røkkr area-of-effect Specials).<br><br>Inflicts Atk/Spd/Def-4 on foe, neutralizes foe''s bonuses, deals damage = 20% of unit''s Spd (excluding area-of-effect Specials), reduces damage from foe''s attacks by 20% of unit''s Spd (excluding area-of-effect Specials), and neutralizes effects that prevent unit''s counterattacks during combat.','Velocity 3',null,false,400,'Infantry','Red Sword,  Blue Lance,  Green Axe',null,'0,0,0,0,0',null,null,'random_owner'),
  ('Divine Rumble','Divine Rumble','Divine Rumble','SID_真天刻の拍動','special',null,null,'When Special triggers, boosts damage by unit''s Spd.<br><br>At start of turn, and at start of enemy phase (except for in Summoner Duels), for unit and allies within 3 spaces of unit, grants 【Prof''s Guidance Skill】and【Dodge】for 1 turn, and if Special cooldown count is at its maximum value, grants Special cooldown count-1.<br><br>If foe initiates combat and unit''s Spd > foe''s Spd, unit can counterattack before foe''s first attack during combat.<br><br>Reduces damage from foe''s first attack by X% (if unit initiates combat or during unit''s first combat initiated by foe each turn, X = 80; otherwise, X = 40; "first attack" normally means only the first strike; for effects that grant "unit attacks twice," it means the first and second strikes), and reduces damage from foe''s follow-up attack by 40% during combat, and also, if decreasing the Spd difference necessary to make a follow-up attack by 10 would allow unit to trigger a follow-up attack (excluding guaranteed or prevented follow-ups), triggers 【Potent Follow 100%】during combat.<br><br>【Prof''s Guidance Skill】<br>While unit lives, unit gets 2× SP after combat or after using an Assist skill (only highest value applied; does not stack).<br><br>Grants Atk/Spd/Def/Res+5 to unit, unit deals +7 damage (excluding area-of-effect Specials), and reduces damage from foe''s attacks by 7 during combat (excluding area-of-effect Specials), and grants Special cooldown count-1 after combat.<br><br>【Dodge】<br>If unit''s Spd > foe''s Spd, reduces damage from attacks during combat and from area-of-effect Specials (excluding Røkkr area-of-effect Specials) by percentage = difference between stats × 4 (max 40%).<br><br>【Potent Follow 100%】<br>Triggers an additional follow-up attack immediately after unit''s standard follow-up attack and deals damage = 100% of unit''s normal attack damage (if unit cannot make a follow-up attack, this effect triggers when the standard follow-up attack would occur; this effect is treated like a follow-up attack, so effects like "reduce damage by X%" still apply, but this effect is not affected by effects that prevent follow-ups or "attacks twice" effects; only highest value applied; does not stack).','Dragon Fang',null,true,500,'Infantry,  Armored,  Cavalry,  Flying',null,null,null,5,null,'offensive_special,random_owner'),
  ('Dour Baton','Dour Baton','Dour Baton','SID_物陰からのバトン','weapon',2,null,'Accelerates Special trigger (cooldown count-1).<br><br>For unit, allies within 3 spaces of unit, and allies on the map with【Anathema】active, grants Atk/Spd/Def/Res+X (for unit, X = 15; for allies, X = 5), neutralizes foe''s bonuses, and grants Special cooldown count-Y to unit or ally before their first attack during combat (Y = number of allies on the map, excluding unit, with 【Anathema】active; max 3 for unit; max 2 for allies) (effects do not stack even if ally conditions overlap).<br><br>Grants bonus to unit''s Atk = unit''s maximum Special cooldown count value × 4, reduces damage from foe''s attacks by 15 (excluding area-of-effect Specials), and neutralizes effects that guarantee foe''s follow-up attacks and effects that prevent unit''s follow-up attacks during combat, and also, if decreasing the Spd difference necessary to make a follow-up attack by 10 would allow unit to trigger a follow-up attack (excluding guaranteed or prevented follow-ups), triggers【Potent Follow 100%】 during combat.<br><br>【Anathema】<br>Inflicts Spd/Def/Res-4 on foes within 3 spaces of unit during combat.<br><br>【Potent Follow 100%】<br>Triggers an additional follow-up attack immediately after unit''s standard follow-up attack and deals damage = 100% of unit''s normal attack damage (if unit cannot make a follow-up attack, this effect triggers when the standard follow-up attack would occur; this effect is treated like a follow-up attack, so effects like "reduce damage by X%" still apply, but this effect is not affected by effects that prevent follow-ups or "attacks twice" effects; only highest value applied; does not stack).','Atlas weapon',null,true,400,'Infantry,  Armored,  Cavalry,  Flying','Colorless Tome',14,'0,14,0,0,0',-1,null,null),
  ('DR Tenet Hone','D/R Tenet Hone','D/R Tenet Hone','SID_守魔信念・弱化無効','passivec',null,null,'At start of player phase or enemy phase, grants 【Bulwark】to unit for 1 turn, and grants Def/Res+6 and "neutralizes penalties on unit during combat" to unit and allies within 2 spaces of unit for 1 turn.<br><br>Grants bonus to unit''s Def/Res = number of allies within 3 rows or 3 columns centered on unit × 2 (max 6), unit deals +5 damage (excluding area-of-effect Specials), and reduces damage from foe''s first attack by 5 during combat ("first attack" normally means only the first strike; for effects that grant "unit attacks twice," it means the first and second strikes).<br><br>【Bulwark】<br>Foes with Range = 1 cannot move through spaces adjacent to unit (does not affect foes with Pass skills). Foes with Range = 2 cannot move through spaces within 2 spaces of unit (does not affect foes with Pass skills).','DefRes Oath 3',null,false,300,'Infantry','Red Sword,  Blue Lance,  Green Axe,  Red Breath,  Blue Breath,  Green Breath,  Colorless Breath,  Red Beast,  Blue Beast,  Green Beast,  Colorless Beast',null,'0,0,0,0,0',null,null,'random_owner'),
  ('Greil Flag','Greil Flag','Greil Flag','SID_グレイル傭兵団の旗','weapon',1,null,'Accelerates Special trigger (cooldown count-1).<br><br>At start of turn, grants Atk/Def/Res 【Great Talent】+2 to unit and allies within 3 rows or 3 columns centered on unit.<br><br>After combat, if unit attacked, grants Atk/Def/Res【Great Talent】+4 to unit and allies within 3 rows or 3 columns centered on unit.<br><br>Grants Atk/Spd/Def/Res+15 to unit, neutralizes foe''s bonuses to Atk/Def, unit deals +25 damage (excluding area-of-effect Specials), reduces damage from foe''s attacks by 15 (excluding area-of-effect Specials), reduces damage from foe''s Specials by an additional 15 (excluding area-of-effect Specials), and grants Special cooldown count-2 to unit before unit''s first follow-up attack during combat.<br><br>(This skill grants max of【Great Talent】+20 for unit and 【Great Talent】+10 for allies.)<br><br>【Great Talent】<br>Adds value of Great Talent (+X) to specified stats (until end of battle; max value of X is determined by the stat reaching the limit of 99, each stat calculated separately and cannot exceed max value for each skill; stat increases are not treated as Bonus effects).','Silver Sword',null,true,400,'Infantry,  Armored,  Cavalry,  Flying','Red Sword',16,'0,16,0,0,0',-1,null,null),
  ('Guiding Lance','Guiding Lance','Guiding Lance','SID_教え導く師の槍','weapon',1,null,'Accelerates Special trigger (cooldown count-1). Unit can counterattack regardless of foe''s range.<br><br>At start of turn, grants Atk/Spd 【Great Talent】+2 to unit and allies within 3 rows or 3 columns centered on unit.<br><br>After combat, if unit attacked, grants Atk/Spd 【Great Talent】+4 to unit and allies within 3 rows or 3 columns centered on unit.<br><br>Grants Atk/Spd/Def/Res+15 to unit, unit deals +25 damage (excluding area-of-effect Specials), reduces damage from foe''s attacks by 15 (excluding area-of-effect Specials), reduces damage from foe''s Specials by an additional 15 (excluding area-of-effect Specials), and neutralizes effects that inflict "Special cooldown charge -X" on unit during combat.<br><br>Unit can use the following【Style】:<br>――――― Sublime Heaven Style ―――――<br>Unit can attack foes 3 spaces away (unit cannot attack adjacent foes).<br><br>Grants Special cooldown count-1 to unit before unit''s first attack during combat. If foe uses dragon or beast damage and unit''s Special triggers, deals damage = 20% of unit''s Atk (excluding area-of-effect Specials).<br><br>Cannot move through spaces within 3 spaces of foe that has triggered the Bulwark effect (does not apply if unit has a Pass skill). Unit suffers a counterattack if any of the following conditions are met: foe is armored with Range = 1 or foe can counterattack regardless of unit''s range.<br><br>After-combat movement effects do not occur. Skill effect''s Range is treated as 1. Once used, this Style cannot be used for two turns.<br>――――――――――――――――――――――――<br>(This skill grants max of【Great Talent】+20 for unit and【Great Talent】+10 for allies.)<br><br>【Great Talent】<br>Adds value of Great Talent (+X) to specified stats (until end of battle; max value of X is determined by the stat reaching the limit of 99, each stat calculated separately and cannot exceed max value for each skill; stat increases are not treated as Bonus effects).<br><br>【Style】<br>Change Style using the Style button at the bottom of the screen.<br><br>A unit''s Style is only active when that unit is taking an action. Style use is disabled when unit is deployed using Pair Up or when unit is equipped with multiple skills that have a Style.','Silver Lance',null,true,400,'Infantry,  Armored,  Cavalry,  Flying','Blue Lance',16,'0,16,0,0,0',-1,null,null),
  ('Long-Dead','Long-Dead','Long-Dead','SID_真あの世行きよ…','passivea',null,null,'Grants Atk/Spd/Def/Res+9.<br><br>At start of player phase or enemy phase, grants【Anathema】,【Pulse Follow】, and 【True Charge】to unit and allies within 3 spaces of unit for 1 turn.<br><br>Unit deals +X × 3 damage (excluding area-of-effect Specials), reduces damage from foe''s attacks by X × 20% (excluding area-of-effect Specials), and reduces damage from foe''s attacks by an additional X × 3 during combat (excluding area-of-effect Specials), and also, if X ≥ 2, foe cannot trigger Specials during combat (excluding area-of-effect Specials).<br><br>After combat, restores X × 3 HP to unit.<br><br>(X = number of allies on the map with 【Anathema】active, excluding unit; max 3.)<br><br>【Anathema】<br>Inflicts Spd/Def/Res-4 on foes within 3 spaces of unit during combat.<br><br>【Pulse Follow】<br>Grants Special cooldown count-2 to unit before unit''s first follow-up attack during combat.<br><br>【True Charge】<br>Unit can move up to 3 spaces in any cardinal direction without being affected by movement obstruction effects from skills. (Cannot move through foes or terrain that blocks movement. Granted movement treated as Warp movement.)',null,null,true,300,'Infantry,  Armored,  Cavalry,  Flying',null,null,'0,9,9,9,9',null,null,'random_owner'),
  ('Mighty Growl','Mighty Growl','Mighty Growl','SID_真肉体の咆哮','special',null,null,'When Special triggers, boosts damage by unit''s Def.<br><br>For unit and allies within 3 rows or 3 columns centered on unit, grants Atk/Spd/Def/Res+X (X = highest bonus on each stat between unit and allies on the map; calculates each stat bonus independently), and grants Special cooldown count-Y to unit or ally before their first attack during combat (for unit, Y = highest total bonuses among unit and allies on the map ÷ 12; for allies Y = highest total bonuses among unit and allies on the map ÷18; rounded down).<br><br>If unit''s Atk at start of combat ≥ foe''s Atk-5, inflicts Atk/Def-7 on foe during combat.<br><br>If unit''s Def at start of combat ≥ foe''s Def-5, inflicts Atk/Def-7 on foe during combat.<br><br>Reduces damage from foe''s attacks by 40% (excluding area-of-effect Specials) and unit makes a guaranteed follow-up attack during combat.','Ignis',null,true,500,'Infantry,  Armored,  Cavalry,  Flying',null,null,null,5,null,'offensive_special,random_owner'),
  ('Pulse Follow Con','Pulse Follow Con','Pulse Follow Con','SID_追撃の鼓動・術策','passivec',null,null,'At start of player phase or enemy phase, if any foes within 3 rows or 3 columns centered on unit have Res < unit''s Res+5, inflicts 【Exposure】and【Discord】on those foes through their next actions.<br><br>Grants bonus to unit''s Atk/Spd = unit''s max Special cooldown count value + 2, reduces damage from foe''s first attack by 5 ("first attack" normally means only the first strike; for effects that grant "unit attacks twice," it means the first and second strikes), and grants Special cooldown count-2 to unit before unit''s first follow-up attack during combat.<br><br>【Exposure】<br>Foe''s attacks deal +10 damage.<br><br>【Discord】<br>Inflicts Atk/Spd/Def/Res-X on unit during combat (X = 2 + number of allies within 2 spaces of unit; max 5).','Times Pulse 3',null,false,300,'Infantry',null,null,'0,0,0,0,0',null,null,'random_owner')
